43	func (h *handler) register(w http.ResponseWriter, r *http.Request) {
44		var request struct {
45			ID   string `json:"id"`
46			Site string `json:"site"`
47		}
48		if err := decodeJSON(r, &request); err != nil || strings.TrimSpace(request.ID) == "" {
49			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "id is required"})
50			return
51		}
52		device, created, err := h.store.Register(strings.TrimSpace(request.ID), strings.TrimSpace(request.Site))
53		if errors.Is(err, ErrStorageUnavailable) {
54			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
55			return
56		}
57		if err != nil {
58			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
59			return
60		}
61		status := http.StatusOK
62		if created {
63			status = http.StatusCreated
64		}
65		writeJSON(w, status, device)
66	}
