68	func (h *handler) telemetry(w http.ResponseWriter, r *http.Request) {
69		values := map[string]float64{}
70		if err := decodeJSON(r, &values); err != nil || len(values) == 0 {
71			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "telemetry values are required"})
72			return
73		}
74		if !finiteValues(values) {
75			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "telemetry values must be finite"})
76			return
77		}
78		device, err := h.store.RecordTelemetry(r.PathValue("id"), values)
79		if errors.Is(err, ErrDeviceNotFound) {
80			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
81			return
82		}
83		if errors.Is(err, ErrStorageUnavailable) {
84			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
85			return
86		}
87		if err != nil {
88			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
89			return
90		}
91		writeJSON(w, http.StatusAccepted, device)
92	}
