94	type replayRequest struct {
95		BatchID string `json:"batchId"`
96		Samples []struct {
97			EventID    string             `json:"eventId"`
98			ObservedAt string             `json:"observedAt"`
99			Values     map[string]float64 `json:"values"`
100		} `json:"samples"`
101	}
102	
103	func (h *handler) replay(w http.ResponseWriter, r *http.Request) {
104		var request replayRequest
105		if err := decodeSingleJSON(r, &request); err != nil {
106			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
107			return
108		}
109		if strings.TrimSpace(request.BatchID) == "" {
110			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "batchId is required"})
111			return
112		}
113		if len(request.Samples) < 1 || len(request.Samples) > 100 {
114			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "samples must contain between 1 and 100 entries"})
115			return
116		}
117		samples := make([]Sample, len(request.Samples))
118		seenEventIDs := make(map[string]struct{}, len(request.Samples))
119		for i, entry := range request.Samples {
120			eventID := strings.TrimSpace(entry.EventID)
121			if eventID == "" {
122				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "each sample requires a non-blank eventId"})
123				return
124			}
125			if _, dup := seenEventIDs[eventID]; dup {
126				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "eventId values must be unique within a batch"})
127				return
128			}
129			seenEventIDs[eventID] = struct{}{}
130			observedAt, err := time.Parse(time.RFC3339, entry.ObservedAt)
131			if err != nil {
132				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "observedAt must be RFC3339 formatted"})
133				return
134			}
135			if len(entry.Values) == 0 || hasBlankKey(entry.Values) {
136				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "values must be a non-empty map with non-blank metric names"})
137				return
138			}
139			if !finiteValues(entry.Values) {
140				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "values must be finite numbers"})
141				return
142			}
143			samples[i] = Sample{
144				EventID:    eventID,
145				ObservedAt: observedAt.UTC(),
146				Values:     cloneTelemetry(entry.Values),
147			}
148		}
149	
150		receipt, repeat, err := h.store.Replay(r.PathValue("id"), strings.TrimSpace(request.BatchID), samples)
151		if errors.Is(err, ErrDeviceNotFound) {
152			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
153			return
154		}
155		if errors.Is(err, ErrBatchConflict) {
156			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
157			return
158		}
159		if errors.Is(err, ErrStorageUnavailable) {
160			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
161			return
162		}
163		if err != nil {
164			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
165			return
166		}
167		status := http.StatusAccepted
168		if repeat {
169			status = http.StatusOK
170		}
171		writeJSON(w, status, receipt)
172	}
