174	func (h *handler) history(w http.ResponseWriter, r *http.Request) {
175		id := r.PathValue("id")
176		query := r.URL.Query()
177	
178		filter := HistoryFilter{}
179		if raw := strings.TrimSpace(query.Get("from")); raw != "" {
180			from, err := time.Parse(time.RFC3339, raw)
181			if err != nil {
182				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "from must be RFC3339 formatted"})
183				return
184			}
185			filter.From = from.UTC()
186		}
187		if raw := strings.TrimSpace(query.Get("to")); raw != "" {
188			to, err := time.Parse(time.RFC3339, raw)
189			if err != nil {
190				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "to must be RFC3339 formatted"})
191				return
192			}
193			filter.To = to.UTC()
194		}
195		if !filter.From.IsZero() && !filter.To.IsZero() && filter.From.After(filter.To) {
196			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "from must not be after to"})
197			return
198		}
199	
200		limit := 20
201		if raw := strings.TrimSpace(query.Get("limit")); raw != "" {
202			value, err := strconv.Atoi(raw)
203			if err != nil || value < 1 || value > 100 {
204				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "limit must be between 1 and 100"})
205				return
206			}
207			limit = value
208		}
209	
210		var afterIndex, highWater int64
211		rawCursor := strings.TrimSpace(query.Get("cursor"))
212		if rawCursor != "" {
213			// An unknown device is always 404, even with a malformed or foreign
214			// cursor; cursor problems on a registered device are 400.
215			if !h.store.Exists(id) {
216				writeJSON(w, http.StatusNotFound, map[string]string{"error": ErrDeviceNotFound.Error()})
217				return
218			}
219			cursor, err := decodeCursor(rawCursor)
220			if err != nil || cursor.DeviceID != id ||
221				!bytes.Equal(cursor.IID, h.store.instanceID()) ||
222				!cursor.From.Equal(filter.From) || !cursor.To.Equal(filter.To) {
223				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid cursor"})
224				return
225			}
226			afterIndex, highWater = cursor.ScanPos, cursor.HighWater
227		}
228	
229		events, appliedBound, nextIndex, hasMore, err := h.store.History(id, filter, afterIndex, highWater, limit)
230		if errors.Is(err, ErrDeviceNotFound) {
231			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
232			return
233		}
234		if err != nil {
235			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
236			return
237		}
238		highWater = appliedBound
239	
240		var nextCursor any
241		if hasMore {
242			nextCursor = encodeCursor(pageCursor{
243				DeviceID:  id,
244				From:      filter.From,
245				To:        filter.To,
246				HighWater: highWater,
247				ScanPos:   nextIndex,
248				IID:       h.store.instanceID(),
249			})
250		}
251	
252		writeJSON(w, http.StatusOK, map[string]any{
253			"deviceId":   id,
254			"events":     events,
255			"nextCursor": nextCursor,
256		})
257	}
