	r := doRequest(t, h, http.MethodGet, "/v1/devices/gw/tasks/1", "")
	if r.Code != http.StatusServiceUnavailable {
		t.Fatalf("timeout read = %d, want 503: %s", r.Code, r.Body.String())
	}
